export const BOARD_CSS = ":root {\n  color-scheme: light;\n  --font-sans: ui-sans-serif, -apple-system, BlinkMacSystemFont, \"Segoe UI\",\n    Roboto, \"Helvetica Neue\", Arial, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  --font-mono: ui-monospace, \"SF Mono\", SFMono-Regular, Menlo, Consolas,\n    \"Liberation Mono\", monospace;\n\n  --canvas: #f4f4f1;\n  --surface: #ffffff;\n  --surface-2: #efefeb;\n  --surface-3: #e7e7e1;\n  --ink: #17181a;\n  --ink-2: #3d4046;\n  --muted: #6b6f76;\n  --faint: #9a9ea6;\n  --line: #e2e2dc;\n  --line-strong: #c9c9c1;\n  --accent: #2447d6;\n  --accent-soft: #e8ecfb;\n  --danger: #b3261e;\n  --warn: #8a5a00;\n  --ok: #2e6b4f;\n\n  --radius-sm: 4px;\n  --radius: 6px;\n  --topbar: 48px;\n  --toolbar: 44px;\n  --lane: 272px;\n  --sheet: 380px;\n  --shadow-sheet: 0 24px 64px rgb(20 20 20 / 0.14), 0 2px 8px rgb(20 20 20 / 0.08);\n  --shadow-toast: 0 8px 32px rgb(20 20 20 / 0.14);\n}\n\n@media (prefers-color-scheme: dark) {\n  :root {\n    color-scheme: dark;\n    --canvas: #0d0f12;\n    --surface: #14171c;\n    --surface-2: #1b1f26;\n    --surface-3: #232830;\n    --ink: #e9ebee;\n    --ink-2: #c3c7ce;\n    --muted: #9aa1ab;\n    --faint: #6b727d;\n    --line: #252a31;\n    --line-strong: #343b45;\n    --accent: #8aa4ff;\n    --accent-soft: #1c2540;\n    --danger: #ff8a80;\n    --warn: #e0b25c;\n    --ok: #7fc3a0;\n    --shadow-sheet: 0 24px 64px rgb(0 0 0 / 0.55), 0 2px 8px rgb(0 0 0 / 0.4);\n    --shadow-toast: 0 8px 32px rgb(0 0 0 / 0.45);\n  }\n}\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\nhtml,\nbody,\n#app {\n  height: 100%;\n}\n\nbody {\n  margin: 0;\n  overflow: hidden;\n  background: var(--canvas);\n  color: var(--ink);\n  font: 13px/1.45 var(--font-sans);\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n  color: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\na {\n  color: var(--accent);\n  text-decoration-thickness: 1px;\n  text-underline-offset: 2px;\n}\n\n::selection {\n  background: var(--accent-soft);\n}\n\n:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  padding: 0;\n  margin: -1px;\n  overflow: hidden;\n  clip: rect(0, 0, 0, 0);\n  white-space: nowrap;\n  border: 0;\n}\n\n/* Shell */\n\n.app {\n  height: 100vh;\n  height: 100dvh;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.topbar {\n  flex: 0 0 auto;\n  height: var(--topbar);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 0 16px;\n  background: var(--surface);\n  border-bottom: 1px solid var(--line);\n}\n\n.brand {\n  font-size: 14px;\n  font-weight: 650;\n  letter-spacing: -0.01em;\n}\n\n.topbar-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.live {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 11px;\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.live-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--faint);\n}\n\n.live.is-online .live-dot {\n  background: var(--ok);\n}\n\n.live.is-warn .live-dot {\n  background: var(--warn);\n}\n\n.live.is-bad .live-dot {\n  background: var(--danger);\n}\n\n.live-sub {\n  font: 10px/1 var(--font-mono);\n  color: var(--faint);\n}\n\n/* Buttons */\n\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  height: 28px;\n  padding: 0 10px;\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--ink);\n  font-size: 12px;\n  font-weight: 550;\n  white-space: nowrap;\n}\n\n.btn:hover:not(:disabled) {\n  background: var(--surface-2);\n}\n\n.btn:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.btn-primary {\n  border-color: var(--ink);\n  background: var(--ink);\n  color: var(--canvas);\n}\n\n.btn-primary:hover:not(:disabled) {\n  border-color: var(--ink-2);\n  background: var(--ink-2);\n}\n\n.btn-ghost {\n  border-color: transparent;\n  background: transparent;\n  color: var(--muted);\n}\n\n.btn-ghost:hover:not(:disabled) {\n  background: var(--surface-2);\n  color: var(--ink);\n}\n\n.btn-sm {\n  height: 24px;\n  padding: 0 8px;\n  font-size: 11px;\n}\n\n.kbd {\n  font: 10px/1 var(--font-mono);\n  border: 1px solid currentColor;\n  border-radius: 3px;\n  padding: 2px 4px;\n  opacity: 0.55;\n}\n\n.icon-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 24px;\n  height: 24px;\n  padding: 0;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: transparent;\n  color: var(--muted);\n  font-size: 13px;\n  line-height: 1;\n}\n\n.icon-btn:hover:not(:disabled) {\n  background: var(--surface-2);\n  color: var(--ink);\n}\n\n.icon-btn:disabled {\n  opacity: 0.4;\n  cursor: not-allowed;\n}\n\n/* Toolbar */\n\n.toolbar {\n  flex: 0 0 auto;\n  min-height: var(--toolbar);\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 6px 16px;\n  background: var(--surface);\n  border-bottom: 1px solid var(--line);\n}\n\n.filters {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: wrap;\n}\n\n.filter-search {\n  width: 240px;\n  height: 28px;\n  padding: 0 10px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius-sm);\n  background: var(--canvas);\n  color: var(--ink);\n  font-size: 12px;\n}\n\n.filter-search::placeholder {\n  color: var(--faint);\n}\n\n.filter-search:focus {\n  border-color: var(--accent);\n  background: var(--surface);\n  box-shadow: 0 0 0 2px var(--accent-soft);\n  outline: none;\n}\n\n.filter-select {\n  height: 28px;\n  padding: 0 6px;\n  border: 1px solid transparent;\n  border-radius: var(--radius-sm);\n  background: transparent;\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.filter-select:hover {\n  background: var(--surface-2);\n  color: var(--ink);\n}\n\n.board-count {\n  margin-left: auto;\n  white-space: nowrap;\n  font: 10.5px/1 var(--font-mono);\n  color: var(--faint);\n}\n\n/* Connection banner */\n\n.banner {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 7px 16px;\n  background: var(--surface-2);\n  border-bottom: 1px solid var(--line);\n  color: var(--ink-2);\n  font-size: 12px;\n}\n\n.banner-dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: var(--warn);\n  flex: 0 0 auto;\n}\n\n.banner-action {\n  margin-left: auto;\n}\n\n/* Ticket question drawer */\n\n.ticket-badge {\n  min-width: 14px;\n  color: var(--accent);\n  font: 10px/1 var(--font-mono);\n  font-variant-numeric: tabular-nums;\n}\n\n.ticket-drawer {\n  position: fixed;\n  top: var(--topbar);\n  right: 0;\n  bottom: 0;\n  z-index: 55;\n  width: min(520px, 94vw);\n  display: flex;\n  flex-direction: column;\n  background: var(--surface);\n  border-left: 1px solid var(--line);\n  box-shadow: var(--shadow-sheet);\n  overflow-wrap: anywhere;\n}\n\n.ticket-drawer-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 12px;\n  padding: 16px 16px 12px;\n  border-bottom: 1px solid var(--line);\n}\n\n.ticket-drawer-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 12px 16px 24px;\n}\n\n.ticket-question {\n  display: grid;\n  gap: 8px;\n  padding: 12px 0;\n  border-bottom: 1px solid var(--line);\n}\n\n.ticket-question-meta {\n  display: flex;\n  justify-content: space-between;\n  gap: 8px;\n  color: var(--faint);\n  font: 10.5px/1.4 var(--font-mono);\n}\n\n.ticket-question-task {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.ticket-question-kind {\n  flex: 0 0 auto;\n  text-transform: uppercase;\n}\n\n.ticket-question-text {\n  margin: 0;\n  color: var(--ink);\n  font-size: 13px;\n  line-height: 1.45;\n}\n\n.ticket-result-text {\n  color: var(--ink-2);\n  font-size: 12px;\n  line-height: 1.5;\n  white-space: pre-wrap;\n}\n\n.ticket-result-error {\n  color: var(--danger);\n}\n\n.ticket-result .ticket-question-kind {\n  color: var(--ok);\n}\n\n.ticket-answers {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n}\n\n.ticket-input {\n  flex: 1 1 240px;\n  min-width: 0;\n  min-height: 88px;\n  padding: 8px;\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--ink);\n  font: 12px/1.45 var(--font-sans);\n  resize: vertical;\n}\n\n.ticket-input:focus {\n  border-color: var(--accent);\n  box-shadow: 0 0 0 2px var(--accent-soft);\n  outline: none;\n}\n\n@media (max-width: 720px) {\n  .ticket-drawer {\n    top: auto;\n    left: 0;\n    width: 100%;\n    max-height: 72vh;\n    border-left: 0;\n    border-top: 1px solid var(--line);\n    border-radius: var(--radius) var(--radius) 0 0;\n  }\n}\n\n/* Composer */\n\n.composer {\n  flex: 0 0 auto;\n  max-width: 860px;\n  margin: 12px 16px 0;\n  padding: 10px;\n  background: var(--surface);\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius);\n}\n\n.composer-head {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.composer-heading {\n  margin: 0;\n  font-size: 13px;\n  font-weight: 650;\n}\n\n.composer-stage {\n  font: 10.5px/1 var(--font-mono);\n  color: var(--faint);\n}\n\n.composer-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.composer-input-wrap {\n  flex: 1;\n  min-width: 0;\n}\n\n.composer-input {\n  width: 100%;\n  height: 32px;\n  padding: 0 10px;\n  border: 1px solid var(--line);\n  border-radius: var(--radius-sm);\n  background: var(--canvas);\n  color: var(--ink);\n  font-size: 13px;\n}\n\n.composer-input::placeholder {\n  color: var(--faint);\n}\n\n.composer-input:focus {\n  border-color: var(--accent);\n  background: var(--surface);\n  box-shadow: 0 0 0 2px var(--accent-soft);\n  outline: none;\n}\n\n.composer-details {\n  margin-top: 8px;\n}\n\n.composer-more {\n  display: inline-block;\n  color: var(--muted);\n  font-size: 11px;\n  cursor: pointer;\n}\n\n.composer-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px 12px;\n  margin-top: 8px;\n  padding-top: 8px;\n  border-top: 1px solid var(--line);\n}\n\n.composer-hint {\n  margin: 8px 0 0;\n  color: var(--warn);\n  font-size: 11px;\n}\n\n/* Edit panel */\n\n.editor {\n  flex: 0 0 auto;\n  margin: 12px 16px 0;\n  padding: 12px;\n  background: var(--surface);\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius);\n}\n\n.editor h2 {\n  margin: 0 0 10px;\n  font-size: 14px;\n  font-weight: 650;\n}\n\n.editor-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 10px 12px;\n}\n\n.editor-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 6px;\n  margin-top: 10px;\n}\n\n.field {\n  display: grid;\n  gap: 4px;\n  min-width: 0;\n}\n\n.field label {\n  color: var(--muted);\n  font-size: 11px;\n}\n\n.field input,\n.field select,\n.field textarea {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: var(--radius-sm);\n  background: var(--canvas);\n  color: var(--ink);\n  padding: 6px 8px;\n  font-size: 12px;\n}\n\n.field input,\n.field select {\n  height: 30px;\n}\n\n.field textarea {\n  resize: vertical;\n  min-height: 54px;\n}\n\n.field input:focus,\n.field select:focus,\n.field textarea:focus {\n  border-color: var(--accent);\n  background: var(--surface);\n  box-shadow: 0 0 0 2px var(--accent-soft);\n  outline: none;\n}\n\n/* Workspace */\n\n.workspace {\n  position: relative;\n  flex: 1;\n  min-height: 0;\n  display: flex;\n}\n\n.board-area {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n}\n\n@media (min-width: 721px) {\n  .workspace.has-sheet .board-area {\n    padding-right: var(--sheet);\n  }\n}\n\n.board-scroll {\n  flex: 1;\n  min-height: 0;\n  overflow: auto;\n  padding: 12px 16px 24px;\n}\n\n.board {\n  display: grid;\n  grid-auto-flow: column;\n  grid-auto-columns: minmax(var(--lane), 340px);\n  gap: 10px;\n  align-items: start;\n}\n\n.lane {\n  min-width: 0;\n}\n\n.lane-head {\n  position: sticky;\n  top: 0;\n  z-index: 2;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  padding: 2px 2px 8px;\n  background: var(--canvas);\n}\n\n.lane-title {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  margin: 0;\n  color: var(--ink-2);\n  font-size: 12px;\n  font-weight: 600;\n}\n\n.lane-count {\n  font: 10.5px/1 var(--font-mono);\n  color: var(--faint);\n}\n\n.lane-add {\n  font-size: 15px;\n}\n\n.lane-body {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding-bottom: 16px;\n}\n\n.lane-empty {\n  margin: 2px 0 0;\n  color: var(--faint);\n  font-size: 11px;\n}\n\n.cards {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* Card */\n\n.card {\n  position: relative;\n  padding: 10px 10px 9px 12px;\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  overflow-wrap: anywhere;\n  transition: border-color 120ms ease;\n}\n\n.card::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  top: 10px;\n  bottom: 10px;\n  width: 2px;\n  border-radius: 1px;\n  background: transparent;\n}\n\n.card.p-low::before {\n  background: var(--line-strong);\n  opacity: 0.5;\n}\n\n.card.p-normal::before {\n  background: var(--line);\n}\n\n.card.p-high::before {\n  background: var(--warn);\n}\n\n.card.p-critical::before {\n  background: var(--danger);\n}\n\n.card:hover {\n  border-color: var(--line-strong);\n}\n\n.card.is-selected {\n  border-color: var(--accent);\n}\n\n.card-title {\n  display: block;\n  width: 100%;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--ink);\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 1.35;\n  text-align: left;\n}\n\n.card-title:hover {\n  text-decoration: underline;\n  text-underline-offset: 2px;\n}\n\n.card-desc {\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  margin: 4px 0 0;\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.card-meta {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 8px;\n  color: var(--faint);\n  font: 10.5px/1 var(--font-mono);\n}\n\n.card-meta .dot {\n  width: 2px;\n  height: 2px;\n  border-radius: 50%;\n  background: var(--faint);\n}\n\n.prio-text.p-high {\n  color: var(--warn);\n}\n\n.prio-text.p-critical {\n  color: var(--danger);\n}\n\n.prio-text.p-low {\n  opacity: 0.75;\n}\n\n.card-actions {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  margin-top: 8px;\n  opacity: 0;\n  transition: opacity 120ms ease;\n}\n\n.card:hover .card-actions,\n.card:focus-within .card-actions,\n.card.is-selected .card-actions,\n.card:has(.card-menu[open]) .card-actions {\n  opacity: 1;\n}\n\n.card-primary {\n  height: 22px;\n  padding: 0 6px;\n  border: 0;\n  background: transparent;\n  color: var(--ink-2);\n  font-size: 11px;\n  font-weight: 600;\n  border-radius: var(--radius-sm);\n}\n\n.card-primary:hover:not(:disabled) {\n  background: var(--surface-2);\n  color: var(--ink);\n}\n\n.card-menu {\n  position: relative;\n  margin-left: auto;\n}\n\n.card-menu > summary {\n  list-style: none;\n}\n\n.card-menu > summary::-webkit-details-marker {\n  display: none;\n}\n\n.card-menu[open] > summary {\n  background: var(--surface-2);\n  color: var(--ink);\n}\n\n.menu {\n  position: absolute;\n  right: 0;\n  top: calc(100% + 4px);\n  z-index: 20;\n  min-width: 180px;\n  padding: 4px;\n  background: var(--surface);\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-toast);\n}\n\n.menu-item {\n  display: block;\n  width: 100%;\n  padding: 6px 8px;\n  border: 0;\n  border-radius: var(--radius-sm);\n  background: transparent;\n  color: var(--ink);\n  font-size: 12px;\n  text-align: left;\n}\n\n.menu-item:hover:not(:disabled) {\n  background: var(--surface-2);\n}\n\n.menu-item:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n/* Skeleton */\n\n.skeleton {\n  background: var(--surface-2);\n  border-radius: 3px;\n}\n\n.skeleton-card {\n  display: grid;\n  gap: 8px;\n  padding: 12px;\n  background: var(--surface);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n}\n\n.skeleton-line {\n  height: 7px;\n}\n\n.w-60 {\n  width: 60%;\n}\n\n.w-40 {\n  width: 40%;\n}\n\n/* Empty */\n\n.empty-state {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  padding: 48px 24px;\n  text-align: center;\n}\n\n.empty-state h2 {\n  margin: 0;\n  font-size: 15px;\n  font-weight: 650;\n}\n\n.empty-state p {\n  max-width: 38ch;\n  margin: 0;\n  color: var(--muted);\n  font-size: 12px;\n}\n\n.empty-hint {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--faint) !important;\n  font: 10.5px/1.4 var(--font-mono) !important;\n}\n\n/* Archive */\n\n.archive {\n  flex: 0 0 auto;\n  background: var(--surface);\n  border-top: 1px solid var(--line);\n}\n\n.archive-summary {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 7px 16px;\n  color: var(--muted);\n  font-size: 11px;\n  cursor: pointer;\n  list-style: none;\n}\n\n.archive-summary::after {\n  content: \"▸\";\n  margin-left: auto;\n  color: var(--faint);\n  font-size: 10px;\n  transition: transform 120ms ease;\n}\n\n.archive[open] .archive-summary::after {\n  transform: rotate(90deg);\n}\n\n.archive-summary::-webkit-details-marker {\n  display: none;\n}\n\n.archive-title {\n  color: var(--ink-2);\n  font-weight: 600;\n}\n\n.archive-counts {\n  font: 10.5px/1 var(--font-mono);\n  color: var(--faint);\n}\n\n.archive[open] .archive-summary {\n  border-bottom: 1px solid var(--line);\n}\n\n.archive-body {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 340px));\n  justify-content: start;\n  gap: 16px;\n  padding: 10px 16px 16px;\n  max-height: 38vh;\n  overflow: auto;\n}\n\n.archive-lane .lane-head {\n  position: static;\n  background: transparent;\n}\n\n/* Inspector sheet */\n\n.inspector {\n  position: fixed;\n  top: var(--topbar);\n  right: 0;\n  bottom: 0;\n  z-index: 50;\n  width: min(var(--sheet), 92vw);\n  padding: 16px;\n  overflow-y: auto;\n  background: var(--surface);\n  border-left: 1px solid var(--line);\n  box-shadow: var(--shadow-sheet);\n  overflow-wrap: anywhere;\n}\n\n.inspector h2 {\n  margin: 0;\n  font-size: 15px;\n  font-weight: 650;\n  line-height: 1.3;\n}\n\n.inspector h3 {\n  margin: 16px 0 6px;\n  color: var(--muted);\n  font-size: 11px;\n  font-weight: 600;\n  letter-spacing: 0;\n  text-transform: none;\n}\n\n.inspector p {\n  margin: 6px 0;\n  font-size: 12px;\n}\n\n.inspector-head {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 8px;\n  padding-bottom: 8px;\n  border-bottom: 1px solid var(--line);\n}\n\n.inspector-head h2 {\n  min-width: 0;\n}\n\n.inspector-head button {\n  flex: 0 0 auto;\n}\n\n.inspector-stage {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin: 6px 0 0 !important;\n  color: var(--muted);\n  font: 10.5px/1.4 var(--font-mono);\n}\n\n.inspector-stage .dot {\n  width: 2px;\n  height: 2px;\n  border-radius: 50%;\n  background: var(--faint);\n}\n\n.inspector-next {\n  display: grid;\n  gap: 4px;\n  margin: 12px 0 4px;\n}\n\n.inspector-next-action {\n  width: 100%;\n  height: 30px;\n}\n\n.inspector-next-hint {\n  margin: 0 !important;\n  color: var(--faint);\n  font: 10.5px/1.4 var(--font-mono);\n}\n\n.inspector-fold {\n  margin-top: 16px;\n  padding-top: 8px;\n  border-top: 1px solid var(--line);\n}\n\n.inspector-fold-summary {\n  display: flex;\n  justify-content: space-between;\n  color: var(--muted);\n  font-size: 11px;\n  cursor: pointer;\n  list-style: none;\n}\n\n.inspector-fold-summary::after {\n  content: \"▸\";\n  color: var(--faint);\n  font-size: 10px;\n  transition: transform 120ms ease;\n}\n\n.inspector-fold[open] .inspector-fold-summary::after {\n  transform: rotate(90deg);\n}\n\n.inspector-fold-summary::-webkit-details-marker {\n  display: none;\n}\n\n.inspector-fold[open] .inspector-fold-summary {\n  color: var(--ink);\n}\n\n.inspector-fold h3:first-of-type {\n  margin-top: 10px;\n}\n\n.inspector-nav {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  margin: 10px 0 0;\n}\n\n.inspector-nav a {\n  color: var(--muted);\n  font-size: 11px;\n  text-decoration: none;\n}\n\n.inspector-nav a:hover {\n  color: var(--ink);\n  text-decoration: underline;\n}\n\n.inspector-status,\n.inspector-empty {\n  color: var(--muted);\n  font-size: 11px;\n}\n\n.inspector-waiting {\n  display: grid;\n  gap: 8px;\n}\n\n.inspector-fields {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 3px 12px;\n  margin: 8px 0 0;\n  font-size: 12px;\n}\n\n.inspector-fields dt {\n  color: var(--muted);\n  font-size: 11px;\n}\n\n.inspector-fields dd {\n  min-width: 0;\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.inspector-list,\n.dependency-options,\n.attempt-list {\n  display: grid;\n  gap: 4px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  font-size: 12px;\n}\n\n.inspector-details > p {\n  white-space: pre-wrap;\n}\n\n.inspector-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 10px;\n}\n\n/* Inspector legacy controls */\n\n.task-action {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 26px;\n  padding: 0 8px;\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius-sm);\n  background: var(--surface);\n  color: var(--ink);\n  font-size: 11px;\n  font-weight: 550;\n  white-space: nowrap;\n}\n\n.task-action:hover:not(:disabled) {\n  background: var(--surface-2);\n}\n\n.task-action:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\n.task-action.primary,\n.inspector .primary {\n  border-color: var(--ink);\n  background: var(--ink);\n  color: var(--canvas);\n}\n\n.task-action.primary:hover:not(:disabled) {\n  border-color: var(--ink-2);\n  background: var(--ink-2);\n}\n\n.inspector-banner,\n.inspector-warning,\n.inspector-conflict {\n  display: grid;\n  gap: 6px;\n  margin: 8px 0;\n  padding: 8px 10px;\n  background: var(--surface-2);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n  font-size: 11px;\n}\n\n.inspector-warning {\n  color: var(--warn);\n}\n\n.inspector-conflict p,\n.inspector-banner p {\n  margin: 0;\n}\n\n.inspector-banner {\n  margin-bottom: 12px;\n}\n\n.dependency-block {\n  display: grid;\n  gap: 8px;\n  justify-items: start;\n}\n\n.dependency-block > .inspector-list,\n.dependency-block > .inspector-empty {\n  width: 100%;\n}\n\n.dependency-editor {\n  display: grid;\n  gap: 8px;\n}\n\n.dependency-options {\n  gap: 6px;\n}\n\n.dependency-option {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  cursor: pointer;\n}\n\n.dependency-option input {\n  margin: 3px 0 0;\n  accent-color: var(--accent);\n}\n\n.dependency-missing {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n  color: var(--muted);\n}\n\n.attempt-row {\n  display: grid;\n  gap: 4px;\n  padding: 8px 0;\n  border-top: 1px solid var(--line);\n}\n\n.attempt-row:first-child {\n  border-top: 0;\n}\n\n.attempt-line {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n}\n\n.attempt-kind {\n  color: var(--muted);\n  font-size: 11px;\n}\n\n.attempt-state {\n  color: var(--ink);\n  font-size: 11px;\n  font-weight: 600;\n}\n\n.attempt-review {\n  color: var(--muted);\n  font: 10.5px/1 var(--font-mono);\n}\n\n.attempt-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 4px;\n}\n\n.attempt-outcome {\n  max-width: 180px;\n}\n\n.attempt-queue {\n  display: grid;\n  gap: 8px;\n  padding: 10px;\n  background: var(--surface-2);\n  border: 1px solid var(--line);\n  border-radius: var(--radius);\n}\n\n.attempt-when {\n  margin: 0;\n  color: var(--faint);\n  font: 10.5px/1.4 var(--font-mono);\n}\n\n.inspector-banner .inspector-actions {\n  margin-top: 2px;\n}\n\n/* Toast */\n\n.toast {\n  position: fixed;\n  right: 16px;\n  bottom: 16px;\n  z-index: 60;\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  max-width: 360px;\n  padding: 10px 12px;\n  background: var(--surface);\n  border: 1px solid var(--line-strong);\n  border-radius: var(--radius);\n  box-shadow: var(--shadow-toast);\n  font-size: 12px;\n}\n\n.toast-dot {\n  width: 6px;\n  height: 6px;\n  margin-top: 5px;\n  border-radius: 50%;\n  background: var(--muted);\n  flex: 0 0 auto;\n}\n\n.toast.notice-success .toast-dot {\n  background: var(--ok);\n}\n\n.toast.notice-warning .toast-dot {\n  background: var(--warn);\n}\n\n.toast.notice-error .toast-dot {\n  background: var(--danger);\n}\n\n.toast-text {\n  min-width: 0;\n  color: var(--ink-2);\n}\n\n.toast-close {\n  flex: 0 0 auto;\n  width: 18px;\n  height: 18px;\n  margin-left: auto;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: var(--faint);\n  font-size: 14px;\n  line-height: 1;\n}\n\n.toast-close:hover {\n  color: var(--ink);\n}\n\n/* Responsive */\n\n@media (max-width: 1023px) {\n  .topbar,\n  .toolbar {\n    padding-left: 12px;\n    padding-right: 12px;\n  }\n\n  .filter-search {\n    width: 180px;\n  }\n\n  .inspector {\n    width: min(420px, 96vw);\n  }\n}\n\n@media (max-width: 720px) {\n  .topbar {\n    padding: 0 12px;\n  }\n\n  .brand {\n    font-size: 13px;\n  }\n\n  .toolbar {\n    min-height: 0;\n    padding: 8px 12px;\n  }\n\n  .filters {\n    width: 100%;\n  }\n\n  .filter-search {\n    flex: 1 1 100%;\n    width: auto;\n  }\n\n  .board-scroll {\n    padding: 8px 12px 16px;\n    scroll-snap-type: x mandatory;\n  }\n\n  .board {\n    grid-auto-columns: 82vw;\n  }\n\n  .lane {\n    scroll-snap-align: start;\n  }\n\n  .composer,\n  .editor {\n    margin: 8px 12px 0;\n  }\n\n  .composer-row {\n    flex-wrap: wrap;\n  }\n\n  .composer-input-wrap {\n    flex: 1 1 100%;\n  }\n\n  .composer-grid,\n  .editor-grid {\n    grid-template-columns: 1fr;\n  }\n\n  .archive-body {\n    grid-template-columns: 1fr;\n    max-height: 44vh;\n  }\n\n  .inspector {\n    top: auto;\n    left: 0;\n    width: 100%;\n    height: 85dvh;\n    padding: 12px;\n    border-top: 1px solid var(--line);\n    border-left: 0;\n    border-radius: 10px 10px 0 0;\n  }\n\n  .toast {\n    left: 12px;\n    right: 12px;\n    bottom: 12px;\n    max-width: none;\n  }\n\n  .card-actions {\n    opacity: 1;\n  }\n}\n\n@media (pointer: coarse) {\n  .filter-search,\n  .filter-select,\n  .composer-input,\n  .field input,\n  .field select,\n  .field textarea {\n    font-size: 16px;\n  }\n\n  .card-actions {\n    opacity: 1;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    transition: none !important;\n    animation: none !important;\n    scroll-behavior: auto !important;\n  }\n}\n";
